def _segments(text, spans):
    out = []
    for s in spans:
        if isinstance(s, str):
            out.append(s)
        elif isinstance(s, dict):
            if "text" in s:
                out.append(str(s.get("text", "")))
            else:
                a = int(s.get("start", s.get("begin", 0)))
                b = int(s.get("end", s.get("stop", a)))
                out.append(text[a:b])
        elif isinstance(s, (list, tuple)) and len(s) >= 2:
            out.append(text[int(s[0]):int(s[1])])
        else:
            out.append("")
    return out

def _has(s, words):
    return any(w in s for w in words)

def _heading(s):
    t = s.strip().lower()
    if len(t) > 100:
        return False
    return _has(t, ("obligations", "non-disclosure", "nondisclosure", "permitted use", "restrictions on", "return of", "ownership", "remedies", "term and", "duration", "compelled disclosure", "required disclosure", "no solicitation", "non-solicitation", "miscellaneous", "general provisions"))

def _lead(out, xs, i):
    j = i - 1
    while j >= 0:
        t = xs[j].strip().lower()
        if len(t) <= 100 and (t.endswith(":") or t.endswith("following") or t.endswith("follows") or t in ("the recipient shall", "the receiving party shall", "recipient agrees", "the parties shall")):
            out.add(j)
            j -= 1
        else:
            break

def _definition_blocks(xs):
    blocks = []
    for i, s in enumerate(xs):
        t = s.lower()
        if "confidential information" in t and _has(t, (" means", " shall mean", " includes", " include all", "defined as")):
            e = i + 1
            while e < len(xs):
                q = xs[e].strip().lower()
                if _heading(q):
                    break
                if " means " in q and "confidential information" not in q and len(q) < 180:
                    break
                e += 1
            blocks.append((i, e))
    return blocks

def _intro(out, xs, i):
    j = i - 1
    while j >= 0 and not _heading(xs[j]):
        q = xs[j].lower()
        if _has(q, ("shall not include", "does not include", "shall not apply", "exceptions", "exclusions", "restrictions shall not apply")):
            out.add(j)
            return
        if len(q) > 250:
            return
        j -= 1

def propose_members(text, spans, public_hypothesis_key):
    xs = _segments(text, spans)
    low = [s.lower() for s in xs]
    out = set()
    k = public_hypothesis_key
    if k in ("nda-1", "nda-2", "nda-3"):
        for a, b in _definition_blocks(low):
            z = " ".join(low[a:b])
            take = k == "nda-1"
            if k == "nda-2":
                take = _has(z, ("technical", "business", "financial", "commercial", "marketing", "employee", "customer", "operational", "contractual", "personnel", "all information"))
            if k == "nda-3":
                take = _has(z, ("oral", "verbally", "spoken", "whether written", "regardless of form", "whatever form", "any form whatsoever"))
            if take:
                out.update(range(a, b))
    if k == "nda-10":
        for i, s in enumerate(low):
            if _has(s, ("existence of this agreement", "terms of this agreement", "fact that discussions", "discussions or negotiations", "negotiations are", "public announcement", "subject matter or terms", "fact that information")):
                out.add(i)
                _lead(out, low, i)
    if k in ("nda-12", "nda-13"):
        words = ("independently developed", "independent development", "developed independently", "independently derived", "independently create") if k == "nda-12" else ("from a third party", "from third parties", "third party having", "third party who", "another source", "source other than")
        for i, s in enumerate(low):
            if _has(s, words):
                out.add(i)
                _intro(out, low, i)
                _lead(out, low, i)
    if k == "nda-15":
        for i, s in enumerate(low):
            if _has(s, ("no license", "no licence", "no right", "no rights", "shall remain the property", "remain the exclusive property", "retain all rights", "does not grant any right", "not be construed as granting", "no title", "no interest", "exclusive owner")):
                out.add(i)
                _lead(out, low, i)
    if k == "nda-16":
        ends = ("termination", "expiration", "expiry", "completion", "conclusion", "abandonment", "ceasing", "ceased", "does not wish to proceed", "not consummated", "not execute", "rejected", "assessment period is over")
        for i, s in enumerate(low):
            if _has(s, ends):
                e = i + 1
                while e < len(low) and not _heading(low[e]):
                    e += 1
                if any(_has(low[j], ("return", "destroy", "deliver", "surrender", "delete", "erase")) for j in range(i, e)):
                    out.update(range(i, e))
    if k == "nda-19":
        for i, s in enumerate(low):
            if _has(s, ("shall survive", "will survive", "survive termination", "survive expiration", "continue to be bound", "continue in force", "continue to apply", "remain in effect", "notwithstanding the return", "notwithstanding such return", "held subject to", "after termination", "beyond termination")):
                out.add(i)
                j = i - 1
                while j >= 0 and not _heading(low[j]) and _has(low[j], ("notwithstanding", "retain", "retained", "copies", "confidential information", "(a)", "(b)")):
                    out.add(j)
                    j -= 1
                _lead(out, low, i)
    if k == "nda-20":
        for i, s in enumerate(low):
            if _has(s, ("retain", "retained", "keep one copy", "archiv", "back-up", "backup", "infeasible", "not required to erase", "not required to delete", "return", "destroy", "no copies", "retaining no copies")):
                if _has(s, ("confidential", "information", "data", "material", "copies", "documents", "records")):
                    out.add(i)
                    _lead(out, low, i)
    if k in ("nda-5", "nda-7"):
        classes = ("employee", "personnel", "staff member") if k == "nda-5" else ("agent", "consultant", "advisor", "adviser", "counsel", "accountant", "contractor", "subcontractor", "representative", "third party")
        for i, s in enumerate(low):
            if _has(s, classes) and _has(s, ("disclose", "disclosure", "access", "furnish", "provide", "share", "need to know", "shall not disclose", "may disclose", "only to")):
                out.add(i)
                _lead(out, low, i)
    if k == "nda-17":
        for i, s in enumerate(low):
            if _has(s, ("copy", "reproduce", "duplicate", "reduce to writing", "record", "photograph")) and not (_has(s, ("return", "destroy")) and not _has(s, ("may", "except", "necessary", "consent", "shall not", "not copy"))):
                out.add(i)
                _lead(out, low, i)
    if k == "nda-8":
        for i, s in enumerate(low):
            if _has(s, ("required by law", "required to disclose", "legally compelled", "court order", "subpoena", "legal process", "governmental authority", "regulatory authority")) and _has(s, ("notice", "notify", "consult", "inform", "advise", "provide")):
                out.add(i)
                _lead(out, low, i)
            elif _has(s, ("prompt notice", "promptly notify", "prior written notice")) and "disclos" in s:
                out.add(i)
                _lead(out, low, i)
    if k == "nda-11":
        for i, s in enumerate(low):
            if _has(s, ("reverse engineer", "decompile", "disassemble")):
                out.add(i)
                _lead(out, low, i)
    if k == "nda-18":
        for i, s in enumerate(low):
            if _has(s, ("solicit", "induce", "entice", "offer employment", "offer to hire", "employ or retain", "contract for the services", "standstill")):
                out.add(i)
                _lead(out, low, i)
    if k == "nda-4":
        for i, s in enumerate(low):
            if _has(s, ("solely for", "only for", "no purpose other", "not use", "use only", "except for the purpose", "necessary for the purpose")) and _has(s, ("confidential", "information", "data", "material", "purpose", "evaluation")):
                out.add(i)
                _lead(out, low, i)
    return sorted(out)

